// Domain: The Flow — stage transition lifecycle (moving, advancing, failing back, pausing, resuming, retrying, completing).
import { _appendProcessLog, AUTO_REPORT_MARKER } from '../watch/index.js';
import { emitAlert } from '../observability/alerts.js';
import { isBranchModeEnabled } from '../work/taskBranches.js';
import { normalizeStageType } from '../projectStore.js';
import { buildHumanApprovalContent } from '../reviewCommentFormatter.js';
import { isTerminalTaskStatus, resolveStageLabel, stageElapsedSeconds, clearResumedMarker, findStageByIdOrName, findStageIndexByIdOrName, isEngineOwnerOf } from './stagePolicy.js';
import { resolveStagesForTask } from './taskScheduler.js';
import { killTaskProcess } from './taskControl.js';
import { buildTimelineAttribution } from './runAttribution.js';

/***
 * MARK: releaseEngineOwnership
 * @description Releases the engine to idle and clears every ownership field
 *   in one write, so no partial reset can leave a stranded `activeStageId`
 *   behind for a monitor surface to read. Single home for the reset shape
 *   (used by interruptLiveRun and the checkpoint-release path); the field
 *   list must stay in sync with abortTask's teardown in taskControl.js.
 * @param {Object} store - The TaskStore (mutated in place).
 ***/
function releaseEngineOwnership(store) {
	store.setEngineState({
		status: "idle",
		activeTaskId: null,
		activeProjectId: null,
		activeProjectName: null,
		activeStageId: null,
		activeStageName: null,
		activeStageType: null,
	});
}

/***
 * MARK: interruptLiveRun
 * @description Stops a task's live execution (child process group plus agent
 *   session) and releases engine ownership when it holds it. The task status
 *   itself is left for the caller to set (paused/completed), so the stop is
 *   never mistaken for a stage outcome. Mirrors abortTask's teardown without
 *   its status reset.
 * @returns {boolean} Whether this task owned the engine.
 ***/
function interruptLiveRun(store, projectId, taskId) {
	killTaskProcess(store, taskId);
	if (store.sessionStore && typeof store.sessionStore.get === "function") {
		try {
			const activeSession = store.sessionStore.get(projectId);
			if (typeof activeSession?.abort === "function") {
				activeSession.abort();
			}
		} catch {
			// ignore abort error
		}
	}
	const wasOwner = isEngineOwnerOf(store.engineState, taskId);
	if (wasOwner) {
		releaseEngineOwnership(store);
	}
	return wasOwner;
}

/***
 * MARK: moveToStage
 * @description Moves a task to an explicit workflow stage, updating timestamps, history, and notifying clients.
 * Writes an arrival-centric timeline row: stage = destination, status =
 * Moved/Advanced, duration = time spent in the FROM stage (attributed via
 * durationStage/durationStageId for analytics). This is deliberately NOT
 * paired with the Failed outcome row that precedes it on failback (that row
 * records stage = source): the display layer (buildDisplayTimeline) owns
 * rendering the pair honestly, and the arrival row is load-bearing for
 * diff-stat baselines, so the write pair must stay as-is.
 ***/
export function moveToStage(
	store,
	projectId,
	taskId,
	stageId,
	reason = "Moved",
	bridge = store.eventBridge,
	projectCwd,
	options = {},
) {
	const task = store.getTask(projectId, taskId);
	if (!task) return null;
	const fromStageId = task.currentStageId;
	const durationStartedAt = task.enteredStageAt;
	const durationSeconds = stageElapsedSeconds(task);

	let projStages = [];
	let targetStage = null;
	if (store.projectStore && typeof store.projectStore.getProject === "function") {
		const proj = store.projectStore.getProject(projectId);
		projStages = resolveStagesForTask(proj, task) || [];
		targetStage = findStageByIdOrName(projStages, stageId);
	}
	const toLabel = targetStage?.name || resolveStageLabel(stageId, projStages);
	const fromLabel = fromStageId
		? resolveStageLabel(fromStageId, projStages)
		: null;
	task.currentStageId = stageId;
	// A stage change consumes any startup-recovery priority: the task is no
	// longer sitting where the interruption left it, so it competes as
	// normal work from here on.
	clearResumedMarker(task);

	// Normalized at the transition boundary so a legacy `review` checkpoint
	// parks as human exactly like an explicit `human` stage; the raw type is
	// only kept as a display label.
	const stageType = normalizeStageType(targetStage?.type);
	if (stageType === "human") {
		task.status = "waiting_human";
	} else {
		task.status = "in_stage";
	}
	task.failureReason = null;
	task.lastError = null;

	task.enteredStageAt = new Date().toISOString();
	task.updatedAt = task.enteredStageAt;
	task.history.push({
		timestamp: task.updatedAt,
		action: `${reason} to stage '${toLabel}'`,
	});
	// Arrival rows never carry run attribution: a row's badge must describe
	// the run of the stage the row is headed with, and that stamp happens at
	// agent dispatch (executeStage stamps this stage's own arrival row).
	// Stamping here would put the FROM stage's agent badge on the TO stage's
	// row — visibly misattributing a model to a human / CI stage.
	store._recordTimelineWithDiffStat(
		task,
		{
			stage: toLabel,
			status: reason === "Advanced" ? "Advanced" : "Moved",
			duration: durationSeconds === undefined ? "--" : `${durationSeconds}s`,
			durationSeconds,
			durationStage: fromLabel,
			durationStageId: fromStageId,
			durationStartedAt,
			timestamp: task.updatedAt,
		},
		projectCwd,
		{ useBranches: isBranchModeEnabled(store.projectStore, projectId) },
	);
	// The run that produced this row's duration is over: drop its pending
	// choice so a later transition (e.g. the Completed row) can never
	// inherit a previous stage's model. The run's own badge already sits on
	// its own arrival row, stamped at its dispatch.
	task.currentRunAttribution = null;
	_appendProcessLog(
		task,
		`[INFO] ${reason} from stage ${fromLabel ? `'${fromLabel}'` : "none"} to stage '${toLabel}'`,
	);

	bridge?.emitProcessEvent?.(projectId, "stage:enter", {
		taskId,
		fromStageId,
		stageId,
		stageType,
		stageName: targetStage?.name || stageId,
		reason,
	});
	if (stageType === "human") {
		// Scheduled checkpoint: the same WebSocket emission as before, routed
		// through the alert seam as `task.checkpoint_wait`/`info` so every
		// alert consumer sees the scheduled-vs-unscheduled distinction.
		void emitAlert(bridge, {
			event: "task.checkpoint_wait",
			severity: "info",
			projectId,
			taskId,
			stage: { id: stageId, name: targetStage?.name || stageId, type: stageType },
			message: "Awaiting human approval",
			ui: {
				event: "stage:checkpoint_wait",
				payload: {
					taskId,
					stageId,
					stageName: targetStage?.name || stageId,
					message: "Awaiting human approval",
				},
			},
		});
	}
	store._saveTaskMarkdown(projectCwd, task);

	bridge?.broadcastGlobal?.("TASK_UPDATED", task);

	// Engine-owner reconciliation: the task's stage just changed, so the
	// engine snapshot must move with it in the same transition. Otherwise the
	// badge keeps naming the stage the task left while the card shows the new
	// one — the "ACTIVE: <old stage>" desync reported in task 072e2cfa.
	if (isEngineOwnerOf(store.engineState, taskId)) {
		if (options.operatorMove) {
			// A manual move/jump is an explicit operator override of a live run:
			// the in-flight execution belongs to the stage the task just left,
			// so stop it and release the engine (the same teardown as
			// abort/complete). The task stays parked at the destination.
			// Record the abandoned stage BEFORE interrupting: a command-stage
			// run surfaces the kill as a plain non-zero exit (no
			// operator-abort marker), so without this its settle would fail
			// back with a spurious failureReason and auto-retry, undoing the
			// move. handleStageFailure settles a run whose stage no longer
			// matches the task quietly and consumes this marker.
			// The marker is intentionally memory-only (never written to the
			// task markdown frontmatter): the orphaned run it describes dies
			// with this process, so after a restart there is nothing to
			// quiet — startup recovery re-parks the task via the orphaned
			// running-status collapse instead. A stale marker can therefore
			// never suppress a post-restart failure.
			if (
				fromStageId != null &&
				String(fromStageId) !== String(stageId)
			) {
				task.supersededStageId = fromStageId;
			}
			interruptLiveRun(store, projectId, taskId);
		} else if (store.engineState.status === "checkpoint") {
			// Advancing out of a human checkpoint releases the parked engine.
			releaseEngineOwnership(store);
		} else {
			// Automatic advance/failback while the run settles (or a paused
			// owner): keep the engine state but re-point the displayed stage at
			// the destination so no reader sees a stranded stage.
			store.setEngineState({
				activeStageId: targetStage?.id ?? stageId,
				activeStageName: toLabel,
				activeStageType: stageType,
			});
		}
	}

	return task;
}

/***
 * MARK: advanceStage
 * @description Advances a task to the next sequential stage in the project pipeline and persists to disk.
 *   When leaving a human checkpoint, `humanReview.comments` (line-by-line review
 *   threads) and `humanReview.guidance` are folded into the `# Human approval`
 *   report, so a pass keeps the reviewer's notes in the durable record.
 * @example advanceStage(store, 'p1', 't1', stages, bridge, '/repo', { comments, guidance: 'ship it' })
 * @param {Object} store - TaskStore instance.
 * @param {Object} [humanReview] - `{ comments?: Array, guidance?: string }` for the exiting human stage.
 ***/
export function advanceStage(
	store,
	projectId,
	taskId,
	stages = [],
	bridge = store.eventBridge,
	projectCwd,
	humanReview = {},
) {
	const task = store.getTask(projectId, taskId);
	if (!task) return null;
	// Terminal tasks never advance: a manual complete that lands while a run
	// is in flight must stick when the orphaned run settles.
	if (isTerminalTaskStatus(task.status)) return task;
	let effectiveStages = stages;
	if (!Array.isArray(effectiveStages) || effectiveStages.length === 0) {
		if (
			store.projectStore &&
			typeof store.projectStore.getProject === "function"
		) {
			const proj = store.projectStore.getProject(projectId);
			if (task.workflowId && Array.isArray(proj?.workflows)) {
				const wf = proj.workflows.find((w) => w.id === task.workflowId);
				if (wf?.stages?.length > 0) {
					effectiveStages = wf.stages;
				}
			}
			if (!effectiveStages || effectiveStages.length === 0) {
				effectiveStages = proj?.stages || [];
			}
		}
	}
	if (!Array.isArray(effectiveStages) || effectiveStages.length === 0)
		return task;

	const index = findStageIndexByIdOrName(
		effectiveStages,
		task.currentStageId,
	);
	if (index === -1) {
		const fallback = effectiveStages[0];
		if (!fallback) return task;
		return moveToStage(
			store,
			projectId,
			taskId,
			fallback.id,
			"Advanced (First Stage)",
			bridge,
			projectCwd,
		);
	}
	const exitingStage = effectiveStages.at(index);
	// Human approval reports are written for normalized human checkpoints
	// (legacy `review` included); only agent stages can fail a verdict gate,
	// so a human exit is always a PASS.
	if (normalizeStageType(exitingStage?.type) === "human") {
		// Review comments captured during the checkpoint ride along in the
		// approval report (a line-by-line pass still leaves a written record)
		// and in the optional pass guidance for downstream stages.
		const reviewComments = Array.isArray(humanReview?.comments)
			? humanReview.comments
			: [];
		store.saveStageReport(projectId, taskId, {
			stageName: exitingStage.name || exitingStage.id,
			stageId: exitingStage.id,
			duration: stageElapsedSeconds(task),
			status: "PASSED",
			content: `${AUTO_REPORT_MARKER}\n${buildHumanApprovalContent({
				stageName: exitingStage.name || exitingStage.id,
				guidance: humanReview?.guidance,
				comments: reviewComments,
			})}`,
			projectCwd,
		});
	}
	if (index >= effectiveStages.length - 1) {
		const currentName = effectiveStages.at(index)?.name || "Final Stage";
		bridge?.emitProcessEvent?.(projectId, "stage:complete", {
			taskId,
			stageId: task.currentStageId,
			stageName: currentName,
			nextStageName: null,
			isTerminal: true,
			pipelineFinished: true,
			message: `Stage '${currentName}' complete — pipeline finished`,
		});
		return completeTask(store, projectId, taskId, projectCwd);
	}
	const currentStage = effectiveStages.at(index);
	const nextStage = effectiveStages.at(index + 1);
	bridge?.emitProcessEvent?.(projectId, "stage:complete", {
		taskId,
		stageId: currentStage?.id,
		stageName: currentStage?.name,
		nextStageId: nextStage?.id,
		nextStageName: nextStage?.name,
		isTerminal: false,
		message: `Stage '${currentStage?.name || currentStage?.id}' complete — advancing to '${nextStage?.name || nextStage?.id}'`,
	});
	return moveToStage(
		store,
		projectId,
		taskId,
		nextStage.id,
		"Advanced",
		bridge,
		projectCwd,
	);
}

/***
 * MARK: failbackStage
 * @description Routes a task via its stage failback policy ('start', 'previous', 'abort', or a specific target stage ID).
 ***/
export function failbackStage(
	store,
	projectId,
	taskId,
	stages = [],
	fallbackStageId,
	bridge = store.eventBridge,
	projectCwd,
) {
	const task = store.getTask(projectId, taskId);
	if (!task) return null;
	// Terminal tasks never fail back: a late failure from an orphaned run
	// must not resurrect a task the operator already finished.
	if (isTerminalTaskStatus(task.status)) return task;
	let effectiveStages = stages;
	if (!Array.isArray(effectiveStages) || effectiveStages.length === 0) {
		if (
			store.projectStore &&
			typeof store.projectStore.getProject === "function"
		) {
			const proj = store.projectStore.getProject(projectId);
			if (task.workflowId && Array.isArray(proj?.workflows)) {
				const wf = proj.workflows.find((w) => w.id === task.workflowId);
				if (wf?.stages?.length > 0) {
					effectiveStages = wf.stages;
				}
			}
			if (!effectiveStages || effectiveStages.length === 0) {
				effectiveStages = proj?.stages || [];
			}
		}
	}
	const stage = findStageByIdOrName(effectiveStages, task.currentStageId);
	const policy =
		fallbackStageId || stage?.fallbackStageId || stage?.failback || "previous";
	let targetId;

	if (
		fallbackStageId &&
		findStageByIdOrName(effectiveStages, fallbackStageId)
	) {
		targetId = fallbackStageId;
	} else if (policy === "start") {
		targetId = effectiveStages[0]?.id;
	} else if (policy === "abort") {
		store.updateTask(projectId, taskId, { status: "failed" }, projectCwd);
		task.history.push({
			timestamp: new Date().toISOString(),
			action: "Aborted by failback policy",
		});
		_appendProcessLog(task, `[ERROR] Task aborted by stage failback policy`);
		bridge?.emitProcessEvent?.(projectId, "stage:failback", {
			taskId,
			fromStageId: task.currentStageId,
			targetStageId: "abort",
			aborted: true,
		});
		store._saveTaskMarkdown(projectCwd, task);
		return task;
	} else if (policy === "previous") {
		const index = findStageIndexByIdOrName(
			effectiveStages,
			task.currentStageId,
		);
		targetId =
			index > 0 ? effectiveStages[index - 1].id : effectiveStages[0]?.id;
	} else if (policy === "any" && fallbackStageId) {
		targetId = fallbackStageId;
	} else {
		const targetStage = findStageByIdOrName(effectiveStages, policy);
		if (targetStage) {
			targetId = targetStage.id;
		} else {
			const index = findStageIndexByIdOrName(
				effectiveStages,
				task.currentStageId,
			);
			targetId =
				index > 0 ? effectiveStages[index - 1].id : effectiveStages[0]?.id;
		}
	}
	if (!targetId) return task;
	bridge?.emitProcessEvent?.(projectId, "stage:failback", {
		taskId,
		fromStageId: task.currentStageId,
		targetStageId: targetId,
	});
	return moveToStage(
		store,
		projectId,
		taskId,
		targetId,
		"Failed back",
		bridge,
		projectCwd,
	);
}

/***
 * MARK: completeTask
 * @description Transitions a task to the completed state and records terminal history and timeline.
 ***/
export function completeTask(store, projectId, taskId, projectCwd) {
	const task = store.getTask(projectId, taskId);
	if (!task) return null;
	if (task.status === "completed") return task;
	// Completing a task that is mid-run must also stop the run: otherwise the
	// orphaned execution advances or fails back afterwards and the finished
	// task visibly reverts to an automated stage.
	interruptLiveRun(store, projectId, taskId);
	const durationSeconds = stageElapsedSeconds(task);
	task.status = "completed";
	task.failureReason = null;
	task.lastError = null;
	task.updatedAt = new Date().toISOString();
	task.history.push({
		timestamp: task.updatedAt,
		action: "Completed",
	});
	let completedStages = [];
	if (store.projectStore && typeof store.projectStore.getProject === "function") {
		const proj = store.projectStore.getProject(projectId);
		if (proj) {
			completedStages = resolveStagesForTask(proj, task) || [];
		}
	}
	// Timeline attribution on the terminal row: the Completed row is headed
	// with the FINAL stage's own name, so it carries the final run's
	// pending choice only when that run happened in this stage — the same
	// "a row's badge names the run of the row's own stage" rule as the
	// dispatch-time arrival stamps.
	const runAttribution =
		task.currentRunAttribution &&
		String(task.currentRunAttribution.stageId) === String(task.currentStageId)
			? buildTimelineAttribution(task.currentRunAttribution)
			: null;
	// Final-stage close-out (plan §3.2): the terminal row is headed with the
	// final stage's name, so it owns the final stage's commit range. The
	// success path persists the latest range on the task
	// (`currentStageBoundary`, updated by every finalize); attaching it here
	// lets range attribution measure the final delta instead of opening the
	// terminal row at `+0 -0`. Without boundary data the legacy cumulative
	// behaviour is unchanged.
	const finalBoundaryStart =
		(typeof task.currentStageStartSha === "string" &&
			task.currentStageStartSha.trim()) ||
		task.currentStageBoundary?.start ||
		null;
	const finalBoundaryEnd =
		(typeof task.currentStageEndSha === "string" &&
			task.currentStageEndSha.trim()) ||
		task.currentStageBoundary?.end ||
		null;
	store._recordTimelineWithDiffStat(
		task,
		{
			stage: task.currentStageId
				? resolveStageLabel(task.currentStageId, completedStages)
				: "Final Stage",
			status: "Completed",
			duration: durationSeconds === undefined ? "--" : `${durationSeconds}s`,
			durationSeconds,
			durationStageId: task.currentStageId,
			timestamp: task.updatedAt,
			...(runAttribution || {}),
			...(finalBoundaryStart && finalBoundaryEnd
				? {
						boundaryStartSha: finalBoundaryStart,
						boundaryEndSha: finalBoundaryEnd,
					}
				: {}),
		},
		projectCwd,
		{ useBranches: isBranchModeEnabled(store.projectStore, projectId) },
	);
	task.currentRunAttribution = null;
	store._saveTaskMarkdown(projectCwd, task);
	store.eventBridge?.broadcastGlobal?.("TASK_UPDATED", task);
	return task;
}

/***
 * MARK: pauseTask
 * @description Manually pauses a task's execution and updates engine state.
 ***/
export function pauseTask(store, projectId, taskId, projectCwd) {
	const task = store.getTask(projectId, taskId);
	if (!task) return null;
	// Terminal tasks stay finished: pausing must not revive them.
	if (isTerminalTaskStatus(task.status)) return task;
	// Pausing the active task must halt its live execution, not just flip the
	// status while the agent keeps running to completion behind it.
	const wasOwner = interruptLiveRun(store, projectId, taskId);
	task.status = "paused";
	// A paused task sits out the queue entirely; any startup-recovery
	// priority would be meaningless until an operator resumes it.
	clearResumedMarker(task);
	task.updatedAt = new Date().toISOString();
	store._recordHistory(task, "Task execution paused manually", task.updatedAt);
	store._saveTaskMarkdown(projectCwd, task);

	// Keep the paused task as the engine owner (interruptLiveRun cleared it):
	// the settling run's cleanup recognises its owner and releases the
	// engine to idle instead of stranding a "paused" state with no owner.
	if (wasOwner || isEngineOwnerOf(store.engineState, taskId)) {
		let projectName = projectId;
		try {
			projectName =
				store.projectStore?.getProject?.(projectId)?.name || projectId;
		} catch {
			// display name is best-effort here
		}
		store.setEngineState({
			status: "paused",
			activeTaskId: taskId,
			activeProjectId: projectId,
			activeProjectName: projectName,
		});
	}
	store.eventBridge?.broadcastGlobal?.("TASK_UPDATED", task);
	return task;
}

/***
 * MARK: resumeTask
 * @description Resumes a paused or interrupted task and dispatches stage execution.
 ***/
export async function resumeTask(
	store,
	projectId,
	taskId,
	{
		stages = [],
		projectCwd,
		agentRunner = store.defaultAgentRunner,
		promptEngine = store.defaultPromptEngine,
		priority = "high",
	} = {},
) {
	const task = store.getTask(projectId, taskId);
	if (!task) return null;

	task.wasInterrupted = false;
	// An operator resume serves the pickup directly (dispatch below), so any
	// startup-recovery priority is consumed here rather than lingering.
	clearResumedMarker(task);
	task.status = "in_stage";
	task.updatedAt = new Date().toISOString();
	store._resetAutoIteration(task);
	store._recordHistory(task, "Task execution resumed manually", task.updatedAt);
	store._saveTaskMarkdown(projectCwd, task);
	store.eventBridge?.broadcastGlobal?.("TASK_UPDATED", task);

	if (agentRunner) {
		await store.executeStage(projectId, taskId, {
			stages,
			projectCwd,
			agentRunner,
			promptEngine,
			priority,
		});
	}
	return store.getTask(projectId, taskId) || task;
}

/***
 * MARK: retryStage
 * @description Retries execution of a failed, aborted, or rejected stage with a
 *   freshly curated prompt. The task gets a genuinely fresh attempt: every
 *   iteration/timeout loop counter restarts and the stage clock re-enters, so
 *   the failback/auto-retry budget starts over (unlike plain execute, which
 *   keeps counting from the current values).
 ***/
export async function retryStage(
	store,
	projectId,
	taskId,
	{
		stages = [],
		projectCwd,
		agentRunner = store.defaultAgentRunner,
		promptEngine = store.defaultPromptEngine,
		priority = "high",
	} = {},
) {
	const task = store.getTask(projectId, taskId);
	if (!task) return null;

	task.wasInterrupted = false;
	// A wedged entry owned by this task would strand the retry dispatch
	// behind a corpse: release the latch synchronously first so the enqueue
	// below runs now. Settles nothing when another task owns the entry.
	try {
		store.settleWedgedEntryForTask?.(
			taskId,
			new Error(`Task ${taskId} retried by operator; queue entry force-settled`),
		);
	} catch {
		// Settle is best-effort; the scheduler wedge watchdog guards alone.
	}
	// A manual retry serves the pickup directly (dispatch below), so any
	// startup-recovery priority is consumed here rather than lingering.
	clearResumedMarker(task);
	// Preserve failureReason/lastError here: executeStage snapshots them at entry
	// to reinject the failure into the next attempt's prompt, then clears them.
	// (Clearing here would blind the retried attempt to the failure that parked it.)
	store._resetAutoIteration(task);
	task.status = "in_stage";
	task.updatedAt = new Date().toISOString();
	store._recordHistory(task, "Stage execution retried manually", task.updatedAt);
	store._saveTaskMarkdown(projectCwd, task);
	store.eventBridge?.broadcastGlobal?.("TASK_UPDATED", task);

	if (agentRunner) {
		await store.executeStage(projectId, taskId, {
			stages,
			projectCwd,
			agentRunner,
			promptEngine,
			priority,
		});
	}
	return store.getTask(projectId, taskId) || task;
}

// Domain: The Flow — preserves the task store's existing public contract.
import { config } from "../config.js";
import { normalizeStageType } from "../projectStore.js";
// NOTE: resolveStageTimeout/resolveProjectTimeout below deliberately use
// raw lowercase comparison instead of normalizeStageType — see the comment
// at resolveStageTimeout for why the fallback contract must stay intact.

/***
 * MARK: clearResumedMarker
 * @description Clears the startup-recovery priority marker in memory only
 *   (no disk write, no store needed). Every state transition that moves a
 *   task away from "sitting where the interruption left it" — stage moves,
 *   manual resume/retry, operator abort, pausing — calls this so the marker
 *   cannot leak onto later, unrelated work. Fails safe: an unset marker is a
 *   no-op and a missing task is ignored. This is the dependency-light twin of
 *   `consumeResumedMarker` (taskScheduler.js), which additionally persists; it
 *   lives here so transition code (stageTransitions/taskControl/
 *   stageFailureRouting) can clear the marker without importing the scheduler
 *   module (which would create a cycle: taskScheduler → stageTransitions is
 *   not currently present, but keeping the predicate layer dependency-free is
 *   the safer direction).
 * @param {Object} task - The task (mutated in place).
 * @returns {boolean} Whether a marker was cleared.
 * @example clearResumedMarker({ resumedAfterInterruption: true, interruptedAt: "…" }) => true
 ***/
export function clearResumedMarker(task) {
	if (!task) return false;
	const hadMarker = task.resumedAfterInterruption === true || !!task.interruptedAt;
	task.resumedAfterInterruption = false;
	task.interruptedAt = null;
	return hadMarker;
}

/***
 * MARK: isTerminalTaskStatus
 * @description Whether a task status is terminal: the engine must never
 *   advance, fail back, retry, or (re)dispatch it. A manual complete
 *   landing mid-run must stick even when the orphaned run settles later.
 * @example isTerminalTaskStatus('completed') => true
 * @example isTerminalTaskStatus('in_stage') => false
 * @param {string} [status] - Task status value.
 * @returns {boolean} True for completed/done/failed/cancelled.
 ***/
export function isTerminalTaskStatus(status) {
	const normalized = String(status || "").toLowerCase();
	return (
		normalized === "completed" ||
		normalized === "done" ||
		normalized === "failed" ||
		normalized === "cancelled"
	);
}

/***
 * MARK: findStageByIdOrName
 * @description Single id-or-name stage lookup shared by every transition and
 *   projection path, so matching semantics cannot drift between writers and
 *   readers (id equality wins; name matches case-insensitively). Fails safe:
 *   a missing/empty ref or stage list resolves to null, never a guess.
 * @example findStageByIdOrName([{ id: '1', name: 'Catchup' }], 'catchup') => { id: '1', name: 'Catchup' }
 * @param {Array<Object>} [stages] - Pipeline stages to search.
 * @param {string} [ref] - Stage id or name.
 * @returns {Object|null} The matched stage, or null.
 ***/
export function findStageByIdOrName(stages, ref) {
	if (ref == null || String(ref).trim() === "") return null;
	if (!Array.isArray(stages)) return null;
	const needle = String(ref);
	return (
		stages.find(
			(s) =>
				String(s?.id) === needle ||
				(s?.name &&
					String(s.name).toLowerCase() === needle.toLowerCase()),
		) || null
	);
}

/***
 * MARK: isEngineOwnerOf
 * @description Whether the given task currently owns the engine (holds the
 *   single-run lock). Ids compare as strings: persisted snapshots and live
 *   records can drift between string and number keys, and a strict compare
 *   would silently treat the owner as a stranger — leaving a stranded engine
 *   behind on operator moves and aborts (task 072e2cfa hardening). Fails
 *   safe: a missing task id or engine owner is never ownership.
 * @example isEngineOwnerOf({ activeTaskId: 't1' }, 't1') => true
 * @param {Object} [engineState] - Engine snapshot.
 * @param {string} [taskId] - Task id to test.
 * @returns {boolean} True when the task holds the engine lock.
 ***/
export function isEngineOwnerOf(engineState, taskId) {
	if (taskId == null || engineState?.activeTaskId == null) return false;
	return String(engineState.activeTaskId) === String(taskId);
}

/***
 * MARK: findStageIndexByIdOrName
 * @description Index twin of `findStageByIdOrName` for ordered-pipeline walks
 *   (advance/failback). Same match semantics; -1 when nothing matches.
 * @example findStageIndexByIdOrName([{ id: '1' }, { id: '2' }], '2') => 1
 * @param {Array<Object>} [stages] - Pipeline stages to search.
 * @param {string} [ref] - Stage id or name.
 * @returns {number} The matched index, or -1.
 ***/
export function findStageIndexByIdOrName(stages, ref) {
	if (ref == null || String(ref).trim() === "") return -1;
	if (!Array.isArray(stages)) return -1;
	const needle = String(ref);
	return stages.findIndex(
		(s) =>
			String(s?.id) === needle ||
			(s?.name && String(s.name).toLowerCase() === needle.toLowerCase()),
	);
}

/***
 * MARK: stageElapsedSeconds
 * @description Measures time spent in the current stage; absent timestamps are not samples.
 * @example stageElapsedSeconds({ enteredStageAt: '2026-01-01T00:00:00Z' }, Date.UTC(2026, 0, 1, 0, 1)) => 60
 ***/
export function stageElapsedSeconds(task, now = Date.now()) {
	const entered = task.enteredStageAt ? Date.parse(task.enteredStageAt) : NaN;
	return Number.isFinite(entered)
		? Math.max(0, (now - entered) / 1000)
		: undefined;
}

/***
 * MARK: resolveEffectiveStageType
 * @description Derives the effective stage type for timeout and stall
 *   calculations. Legacy `deploy` is a normal `ci` stage now; the runtime kind
 *   is not derived from command text. `merge` keeps the merge budget.
 * @example resolveEffectiveStageType({ type: 'ci' }) => 'ci'
 * @example resolveEffectiveStageType({ type: 'merge', command: './deploy.sh --prod' }) => 'merge'
 * @param {Object} [stage]
 * @returns {string}
 ***/
export function resolveEffectiveStageType(stage) {
	if (!stage || typeof stage !== "object") return "agent";
	const rawType = String(stage.type || "").toLowerCase();
	if (rawType === "merge") return "merge";
	// Legacy alias: the removed `deploy` type reads as `ci` everywhere
	// (a deploy command is an ordinary ci stage).
	if (rawType === "deploy") return "ci";
	return rawType || "agent";
}

/***
 * MARK: resolveStageTimeout
 * @description Resolves the effective execution timeout (ms) for a stage.
 *   Uses explicit per-stage override if positive, otherwise the project's
 *   per-type timeout when set, otherwise type-specific config defaults:
 *     - agent / review: config.agentTimeoutMs (default: 1,800,000 ms / 30 min)
 *     - ci / script: config.ciTimeoutMs (default: 600,000 ms / 10 min)
 *     - merge: config.mergeTimeoutMs (default: 1,800,000 ms / 30 min)
 *     - human / unknown: 300,000 ms safe fallback
 * @example resolveStageTimeout({ type: 'agent' }, 'agent', undefined, { agentTimeoutMs: 60000 }) => 60000
 * @param {Object} [stage] - Stage configuration object.
 * @param {string} [stageType] - Stage type ('agent', 'ci', 'merge', etc.).
 * @param {Object} [cfg=config] - Config object.
 * @param {Object} [project] - Project carrying optional per-type timeout overrides.
 * @returns {number} Wall-clock timeout in milliseconds.
 ***/
export function resolveStageTimeout(stage, stageType, cfg = config, project) {
	if (
		stage?.timeout !== undefined &&
		stage?.timeout !== null &&
		stage?.timeout !== ""
	) {
		const parsed = Number(stage.timeout);
		if (Number.isFinite(parsed) && parsed > 0) {
			return parsed;
		}
	}

	// Raw lowercase comparison (not normalizeStageType) is deliberate here:
	// legacy aliases `review`/`script` are mapped explicitly below, while
	// `human` and unknown types keep the 300000 ms safe fallback. Routing
	// through normalizeStageType would collapse unknown → agent and change
	// the fallback contract locked by characterization tests.
	const normalizedType = String(
		stageType || resolveEffectiveStageType(stage) || "agent",
	).toLowerCase();
	const projectTimeout = resolveProjectTimeout(project, normalizedType);
	if (projectTimeout !== undefined) {
		return projectTimeout;
	}
	if (normalizedType === "agent" || normalizedType === "review") {
		return cfg?.agentTimeoutMs ?? 1800000;
	}
	// Legacy alias: the removed `deploy` type reads as `ci` (a deploy
	// command is an ordinary ci stage with the CI budget).
	if (normalizedType === "ci" || normalizedType === "script" || normalizedType === "deploy") {
		return cfg?.ciTimeoutMs ?? 600000;
	}
	if (normalizedType === "merge") {
		return cfg?.mergeTimeoutMs ?? 1800000;
	}
	return 300000;
}

/***
 * MARK: resolveProjectTimeout
 * @description Reads a project's per-type timeout override (agentTimeoutMs,
 *   ciTimeoutMs, mergeTimeoutMs): review stages share the
 *   agent timeout and legacy script stages share the CI timeout, mirroring
 *   the global fallback mapping. Non-positive or non-numeric values fall
 *   through (undefined) so invalid input can never shorten a stage to zero.
 * @example resolveProjectTimeout({ ciTimeoutMs: 5000 }, 'ci') => 5000
 * @example resolveProjectTimeout({ agentTimeoutMs: 0 }, 'agent') => undefined
 * @param {Object} [project] - Project carrying optional timeout overrides.
 * @param {string} [normalizedType] - Lowercased stage type.
 * @returns {number|undefined} Positive timeout in ms, or undefined to fall through.
 ***/
export function resolveProjectTimeout(project, normalizedType) {
	if (!project || typeof project !== "object") return undefined;
	const key =
		normalizedType === "agent" || normalizedType === "review"
			? "agentTimeoutMs"
			: normalizedType === "ci" || normalizedType === "script"
				? "ciTimeoutMs"
				: normalizedType === "merge"
						? "mergeTimeoutMs"
						: null;
	if (!key) return undefined;
	/* eslint-disable-next-line security/detect-object-injection -- key comes from the fixed type-to-field mapping above */
	const raw = project[key];
	if (raw === undefined || raw === null || raw === "") return undefined;
	const parsed = Number(raw);
	if (!Number.isFinite(parsed) || parsed <= 0) return undefined;
	return Math.floor(parsed);
}

/***
 * MARK: runnerStageTimeoutStatus
 * @description Wall-clock check for a Runner claim hold against its stage
 *   budget: a live Runner renewing its lease forever must not outrun the
 *   stage timeout, otherwise an agent stage with a stuck harness sits
 *   claimed indefinitely (the engine watchdog only covers engine-owned
 *   stages). Anchored on the hold's start (execution time), not stage
 *   entry, so queue wait never consumes the budget. Unparseable anchors
 *   never time out — bad data fails open, the budget still applies.
 * @example runnerStageTimeoutStatus({ startedAt: '2026-10-29T19:00:00.000Z', timeoutMs: 1800000, now: Date.parse('2026-10-29T19:00:00.000Z') + 1800001 }) => { timedOut: true, ... }
 * @param {Object} [args] - Check inputs.
 * @param {string|null} [args.startedAt] - Claim hold start (ISO string).
 * @param {number} [args.timeoutMs] - Effective stage budget in ms.
 * @param {number} [args.now] - Clock injection (defaults to Date.now()).
 * @returns {{timedOut: boolean, elapsedMs: number, timeoutMs: number}} Timeout status.
 ***/
export function runnerStageTimeoutStatus({ startedAt, timeoutMs, now = Date.now() } = {}) {
	const startedAtMs = Date.parse(startedAt ?? "");
	if (!Number.isFinite(startedAtMs)) {
		return { timedOut: false, elapsedMs: 0, timeoutMs };
	}
	const elapsedMs = Math.max(0, now - startedAtMs);
	const timedOut =
		Number.isFinite(timeoutMs) && timeoutMs > 0 && elapsedMs > timeoutMs;
	return { timedOut, elapsedMs, timeoutMs };
}

/***
 * MARK: isAutomatedStage
 * @description Whether a stage type is fully scripted (no model runs): `ci`
 *   (absorbs legacy `script` and the removed `deploy` type) or `merge`.
 *   Mirrors the frontend `isAutomatedStage` predicate in
 *   `frontend/src/components/stageTypes.js`; normalization goes through the
 *   single `normalizeStageType` source of truth so legacy types classify
 *   identically everywhere. Unknown/empty types default to `agent`
 *   (fail-visible: monitor pills shown, never silently hidden). A ci stage
 *   whose command runs the deploy script classifies here as automated via
 *   `ci` — no separate arm.
 * @example isAutomatedStage('merge') => true
 * @example isAutomatedStage('agent') => false
 * @param {string} [type] - Stage type value.
 * @returns {boolean} True for ci/merge stages.
 ***/
export function isAutomatedStage(type) {
	if (!type || typeof type !== "string") return false;
	const normalized = normalizeStageType(type);
	return normalized === "ci" || normalized === "merge";
}

/***
 * MARK: resolveStageLabel
 * @description Resolves the human-readable label for a stage reference (id or
 *   name). Matches by stage id first, then case-insensitively by stage name,
 *   and returns the stage's display name when found. Falls back to the
 *   reference itself when no stage matches (or no stages are available), and
 *   to 'unknown' when the reference is empty. Used so history/timeline entries
 *   record stage names, which stay meaningful even after stages are renamed,
 *   reordered, inserted, or deleted.
 * @example resolveStageLabel('1', [{ id: '1', name: 'Idea' }]) => 'Idea'
 * @example resolveStageLabel('idea', [{ id: '1', name: 'Idea' }]) => 'Idea'
 * @example resolveStageLabel('42', [{ id: '1', name: 'Idea' }]) => '42'
 * @example resolveStageLabel('', [{ id: '1', name: 'Idea' }]) => 'unknown'
 * @example resolveStageLabel('1', []) => '1'
 * @param {string} [stageRef] - Stage id or name to resolve.
 * @param {Array<Object>} [stages=[]] - The workflow's stages.
 * @returns {string} Human-readable stage label (stage name when resolvable).
 ***/
export function resolveStageLabel(stageRef, stages = []) {
	const ref =
		stageRef === undefined || stageRef === null ? "" : String(stageRef).trim();
	if (!ref) return "unknown";
	if (Array.isArray(stages)) {
		const match = stages.find(
			(s) =>
				String(s?.id) === ref ||
				(s?.name && String(s.name).toLowerCase() === ref.toLowerCase()),
		);
		if (match?.name) return match.name;
	}
	return ref;
}

/***
 * MARK: resolveStage
 * @description Picks the stage a task lands in: an explicit stageId, else
 *   the project's current stage, else the first stage, else a safe fallback.
 * @example resolveStage(project, '2') => { id: '2', name: 'Plan', ... }
 * @param {Object|undefined} project
 * @param {string|undefined} stageId
 * @returns {Object} The resolved stage.
 ***/
export function resolveStage(project, stageId) {
	if (stageId && Array.isArray(project?.stages)) {
		const found = project.stages.find(
			(s) =>
				String(s.id) === String(stageId) ||
				(s.name && String(s.name).toLowerCase() === String(stageId).toLowerCase()),
		);
		if (found) return found;
	}
	return (
		project?.stages?.[0] ||
		(Array.isArray(project?.stages) &&
			project.stages.find(
				(s) => String(s.id) === String(project.currentStageId),
			)) || {
			id: "initial-step",
			name: "Initial Step",
			prompt: "Execute the task",
			type: "agent",
		}
	);
}

import { normalizeStageType } from '../stageTypes.js';

/***
 * MARK: isTaskCompleted
 * @description Single source of truth for the task completion status vocabulary.
 * A task counts as completed when its status is 'completed' or the legacy alias 'done'.
 * Use this instead of inline status checks so the whole UI stays in sync if the
 * status vocabulary ever changes (see stageAnalytics and collapsed rail badges).
 * @example isTaskCompleted({ status: 'completed' }) => true
 * @example isTaskCompleted({ status: 'in_stage' }) => false
 * @example isTaskCompleted(null) => false
 * @param {Object} [task] - The task object (or null/undefined for safety).
 * @returns {boolean} True when the task is completed.
 ***/
export function isTaskCompleted(task) {
  return task?.status === 'completed' || task?.status === 'done';
}

/***
 * MARK: selectStagePresentation
 * @description Single source of truth for how the current-stage row presents:
 *   settled tasks (completed/failed/interrupted/blocked) never render a live
 *   ticking row — a parked failure shows a static PARKED label — while only
 *   genuinely executing tasks tick. A settled `failed` merge task is parked
 *   (needs operator retry), not active: rendering it ACTIVE with a growing
 *   "Nm in stage" timer is what made parked merge failures look stuck.
 * @example selectStagePresentation({ status: 'failed' }) => { label: 'PARKED', tone: 'parked', ticking: false }
 * @example selectStagePresentation({ status: 'in_stage' }) => { label: 'ACTIVE', tone: 'active', ticking: true }
 * @param {Object} [task] - The task object (or null/undefined for safety).
 * @returns {{ label: string, tone: string, ticking: boolean }} Presentation verdict.
 ***/
export function selectStagePresentation(task) {
  const status = typeof task?.status === 'string' ? task.status.trim().toLowerCase() : '';
  if (status === 'completed' || status === 'done') {
    return { label: 'DONE', tone: 'done', ticking: false };
  }
  if (status === 'failed' || status === 'interrupted' || status === 'blocked') {
    return { label: 'PARKED', tone: 'parked', ticking: false };
  }
  if (status === 'waiting_human' || status === 'waiting-human' || status === 'waiting') {
    return { label: 'WAITING', tone: 'waiting', ticking: false };
  }
  return { label: 'ACTIVE', tone: 'active', ticking: true };
}

/***
 * MARK: formatTaskKey
 * @description Formats a task ID into a standardized #KB-XXXX key in uppercase JetBrains Mono.
 * @example formatTaskKey('73c4560d-1417-4fe1') => '#KB-73C4'
 * @example formatTaskKey('abc-1234-def') => '#KB-ABC1'
 * @example formatTaskKey('t1') => '#KB-T1'
 * @param {string} [taskId]
 * @returns {string} Standardized task key.
 ***/
export function formatTaskKey(taskId) {
  if (!taskId || typeof taskId !== 'string') return '#KB-0000';
  const clean = taskId.replace(/[^a-zA-Z0-9]/g, '');
  const snippet = (clean.length >= 4 ? clean.slice(0, 4) : taskId.slice(0, 4)).toUpperCase();
  return `#KB-${snippet || '0000'}`;
}

/***
 * MARK: formatTaskTitleFirstLine
 * @description Single source of truth for the one-line task title shown on
 * cards, inspector headers, queue rows, and the Now Playing bar. Task goals
 * are markdown: only the first line is shown and a leading `# ` heading
 * marker is stripped. Fails safe: non-string or empty input renders the
 * fallback (default `'Untitled Task'`) instead of a blank or crashed label.
 * @example formatTaskTitleFirstLine({ goal: '# Ship it\nbody' }) => 'Ship it'
 * @example formatTaskTitleFirstLine(null) => 'Untitled Task'
 * @param {Object|string} [taskOrText] - Task object (goal/title) or raw text.
 * @param {string} [fallback='Untitled Task'] - Label when no title line exists.
 * @returns {string} First title line, or the fallback.
 ***/
export function formatTaskTitleFirstLine(taskOrText, fallback = 'Untitled Task') {
  // `||` (not `??`) matches every call site this replaces: an empty goal
  // falls through to the title, exactly like `(goal || title || '')` did.
  const raw =
    typeof taskOrText === 'string'
      ? taskOrText
      : (taskOrText?.goal || taskOrText?.title || '');
  const line =
    typeof raw === 'string' ? raw.split('\n')[0].replace(/^#\s+/, '') : '';
  return line || fallback;
}

/***
 * MARK: getBlockedState
 * @description Single source of truth for whether a task is held up by
 * unfinished prerequisite tasks, and which tasks those are. Prefers the
 * scheduler's isBlocked verdict when the payload carries it so every surface
 * agrees; otherwise derives from blockedBy plus the live task list.
 * @example getBlockedState({ blockedBy: ['a'] }, [{ id: 'a', status: 'in_stage' }]) => { isBlocked: true, blockerIds: ['a'] }
 * @example getBlockedState({ isBlocked: false, blockedBy: ['a'] }, [{ id: 'a', status: 'in_stage' }]) => { isBlocked: false, blockerIds: ['a'] }
 * @param {Object} [task] - The task object (or null/undefined for safety).
 * @param {Array<Object>} [allTasks=[]] - Live task list used to check blocker statuses.
 * @returns {{ isBlocked: boolean, blockerIds: Array<string> }} Blocked verdict plus blocker ids.
 ***/
export function getBlockedState(task, allTasks = []) {
  const liveTasks = Array.isArray(allTasks) ? allTasks : [];
  const blockedBy = Array.isArray(task?.blockedBy) ? task.blockedBy : [];
  const blockerIds =
    Array.isArray(task?.blockers) && task.blockers.length > 0 ? [...task.blockers] : [...blockedBy];
  if (typeof task?.isBlocked === 'boolean') {
    return { isBlocked: task.isBlocked, blockerIds };
  }
  const isBlocked =
    blockedBy.length > 0 &&
    liveTasks.some((t) => blockedBy.includes(t?.id) && t?.status !== 'completed');
  return { isBlocked: Boolean(isBlocked), blockerIds };
}

/***
 * MARK: formatBlockerKeys
 * @description Formats blocker ids as short human-readable #KB-XXXX keys,
 * capped so long blocker lists cannot break a one-line layout.
 * @example formatBlockerKeys(['abc-1234-def']) => '#KB-ABC1'
 * @example formatBlockerKeys(['a-1', 'b-2', 'c-3', 'd-4']) => '#KB-A1, #KB-B2, #KB-C3 +1 more'
 * @param {Array<string>} [blockerIds=[]] - Blocker task ids.
 * @param {Object} [options] - Formatting options.
 * @param {number} [options.max=3] - Maximum keys shown before the +N more suffix.
 * @returns {string} Comma-separated keys, empty string when there are no blockers.
 ***/
export function formatBlockerKeys(blockerIds, { max = 3 } = {}) {
  if (!Array.isArray(blockerIds) || blockerIds.length === 0) return '';
  const limit = Number.isInteger(max) && max > 0 ? max : 3;
  const keys = blockerIds.map((id) => formatTaskKey(id));
  const shown = keys.slice(0, limit);
  const hidden = keys.length - shown.length;
  return hidden > 0 ? `${shown.join(', ')} +${hidden} more` : shown.join(', ');
}

/***
 * MARK: formatTaskTimestamp
 * @description Formats real timestamp with formatted absolute time and/or relative elapsed time in stage.
 * Never outputs hardcoded "Just now".
 * @example formatTaskTimestamp({ enteredStageAt: '2026-08-19T09:00:00Z' }) => '9:00 AM (0m in stage)'
 * @example formatTaskTimestamp({ timeInStage: '2m' }) => '2m in stage'
 * @param {Object} [task] - The task object.
 * @returns {string} Formatted timestamp string.
 ***/
export function formatTaskTimestamp(task) {
  if (!task) return '0m in stage';

  const tsString = task.enteredStageAt || task.updatedAt || task.createdAt || task.timestamp;

  if (!tsString) {
    if (
      typeof task.timeInStage === 'string' &&
      task.timeInStage.trim() &&
      task.timeInStage !== 'Just now'
    ) {
      return task.timeInStage.includes('stage') ? task.timeInStage : `${task.timeInStage} in stage`;
    }
    if (typeof task.timeInStage === 'number' && task.timeInStage > 0) {
      return `${task.timeInStage}m in stage`;
    }
    return '0m in stage';
  }

  const d = new Date(tsString);
  const isValidDate = !Number.isNaN(d.getTime());

  if (!isValidDate) {
    if (
      typeof task.timeInStage === 'string' &&
      task.timeInStage.trim() &&
      task.timeInStage !== 'Just now'
    ) {
      return task.timeInStage.includes('stage') ? task.timeInStage : `${task.timeInStage} in stage`;
    }
    return '0m in stage';
  }

  const timeStr = d.toLocaleTimeString([], { hour: 'numeric', minute: '2-digit' });
  const now = Date.now();
  const elapsedMs = Math.max(0, now - d.getTime());
  const elapsedMinutes = Math.floor(elapsedMs / (1000 * 60));
  const elapsedHours = Math.floor(elapsedMinutes / 60);
  const elapsedDays = Math.floor(elapsedHours / 24);

  let elapsedStr = '0m in stage';
  if (
    typeof task.timeInStage === 'string' &&
    task.timeInStage.trim() &&
    task.timeInStage !== 'Just now'
  ) {
    elapsedStr = task.timeInStage.includes('stage')
      ? task.timeInStage
      : `${task.timeInStage} in stage`;
    return `${timeStr} (${elapsedStr})`;
  }

  if (elapsedDays > 0) {
    elapsedStr = `${elapsedDays}d in stage`;
  } else if (elapsedHours > 0) {
    elapsedStr = `${elapsedHours}h in stage`;
  } else {
    elapsedStr = `${elapsedMinutes}m in stage`;
  }

  return `${timeStr} (${elapsedStr})`;
}

/***
 * MARK: resolveTimelineStageLabel
 * @description Maps a timeline stage label to a human-readable stage name for
 *   display. Stage ids are positional numbers that can change when the
 *   workflow is edited, so legacy timeline entries that recorded a bare
 *   numeric id are mapped (best-effort) onto the current stage with that id.
 *   Labels that are already human-readable names, or numeric labels that match
 *   no current stage, are returned unchanged.
 * @example resolveTimelineStageLabel('1', [{ id: '1', name: 'Idea' }]) => 'Idea'
 * @example resolveTimelineStageLabel('Idea', [{ id: '1', name: 'Idea' }]) => 'Idea'
 * @example resolveTimelineStageLabel('9', [{ id: '1', name: 'Idea' }]) => '9'
 * @param {string} [stageLabel] - Timeline stage label (legacy numeric id or name).
 * @param {Array<Object>} [stages=[]] - The current workflow stages.
 * @returns {string} Display label for the timeline entry.
 ***/
export function resolveTimelineStageLabel(stageLabel, stages = []) {
  const label =
    stageLabel === undefined || stageLabel === null
      ? ''
      : String(stageLabel).trim();
  if (!label || !/^\d+$/.test(label) || !Array.isArray(stages)) return label;
  const match = stages.find((s) => String(s?.id) === label);
  return match?.name || label;
}

/***
 * MARK: RUN_ATTRIBUTION_KEYS
 * @description The timeline run-attribution vocabulary, identical to the
 *   backend `reportMetadata` field names (one concept = one name). Listed
 *   once so the display fail-safe below and any future consumer strip the
 *   same fields.
 ***/
const RUN_ATTRIBUTION_KEYS = ['harnessId', 'modelRef', 'aliasName', 'targetIndex'];

/***
 * MARK: resolveTimelineStageRecord
 * @description Finds the workflow stage record a stored timeline row is
 *   headed with, matching the raw stored label against stage ids and names
 *   (case-insensitive for names, so legacy numeric ids still match). Returns
 *   null when no stage resolves — callers fail open (keep stored fields)
 *   rather than destroy signal for an unknown or renamed stage.
 * @example resolveTimelineStageRecord([{ id: '2', name: 'Review Plan', type: 'human' }], 'Review Plan') => { id: '2', name: 'Review Plan', type: 'human' }
 * @example resolveTimelineStageRecord([{ id: '2', name: 'Review Plan', type: 'human' }], '2') => { id: '2', name: 'Review Plan', type: 'human' }
 * @example resolveTimelineStageRecord([], 'Review Plan') => null
 * @param {Array<Object>} [stages=[]] - The current workflow stages.
 * @param {*} [label] - Raw stored timeline stage label.
 * @returns {Object|null} The matching stage record, or null when unresolved.
 ***/
function resolveTimelineStageRecord(stages, label) {
  if (!Array.isArray(stages) || label === undefined || label === null) return null;
  const raw = String(label).trim();
  if (!raw) return null;
  const lowered = raw.toLowerCase();
  for (const candidate of stages) {
    if (!candidate || typeof candidate !== 'object') continue;
    if (
      candidate.id !== undefined &&
      candidate.id !== null &&
      String(candidate.id).trim() === raw
    ) {
      return candidate;
    }
    if (
      typeof candidate.name === 'string' &&
      candidate.name.trim().toLowerCase() === lowered
    ) {
      return candidate;
    }
  }
  return null;
}

/***
 * MARK: selectDisplayTimeline
 * @description Prepares stored timeline entries for display in the task
 *   history UI, newest entry first. Stored entries are chronological
 *   (oldest first) and must stay that way for persistence, durations, and
 *   analytics — so this maps legacy numeric stage labels to names, drops
 *   exact duplicates, then returns a reversed copy. Never mutates its input
 *   or the stored timeline: stripping happens on the display copies only.
 *
 *   Display fail-safe for run attribution: a row headed with a stage that
 *   positively resolves to a non-agent type (human / ci / merge) has its
 *   run-attribution fields removed, whatever the stored row carries. Stored
 *   rows written before the dispatch-time stamping fix can carry a previous
 *   agent stage's badge on a human / CI arrival row — rendering those fields
 *   would misattribute a model to a stage that never ran one, so display
 *   drops them. Rows whose stage does not resolve (renamed stages, empty
 *   stage list) keep their stored fields: an unknown stage is never assumed
 *   to be human or CI.
 * @example selectDisplayTimeline([{ stage: 'Idea' }, { stage: 'Plan' }]) => [{ stage: 'Plan' }, { stage: 'Idea' }]
 * @example selectDisplayTimeline([], []) => []
 * @param {Array<Object>} [rawTimeline=[]] - Stored timeline entries, oldest first.
 * @param {Array<Object>} [stages=[]] - The current workflow stages.
 * @returns {Array<Object>} Display entries, most recent first.
 ***/
export function selectDisplayTimeline(rawTimeline = [], stages = []) {
  const raw = Array.isArray(rawTimeline) ? rawTimeline : [];
  const seen = new Set();
  // Stage ids are positional and can change when the workflow is edited, so
  // legacy numeric labels are mapped (best-effort) onto the current stage's
  // human-readable name for display; names pass through unchanged.
  const deduped = raw
    .map((item) => {
      const mapped = {
        ...item,
        stage: resolveTimelineStageLabel(item?.stage, stages),
      };
      // Fail-safe, display copies only: a non-agent stage never ran a model,
      // so its rows never show a badge — even for legacy stored rows that
      // still carry a previous agent run's fields.
      const record =
        resolveTimelineStageRecord(stages, item?.stage) ||
        resolveTimelineStageRecord(stages, mapped.stage);
      if (record && normalizeStageType(record.type) !== 'agent') {
        for (const key of RUN_ATTRIBUTION_KEYS) {
          delete mapped[key];
        }
      }
      return mapped;
    })
    .filter((item) => {
      const key = `${item.stage || ''}::${item.timestamp || ''}::${item.status || ''}::${item.duration || ''}`;
      if (seen.has(key)) return false;
      seen.add(key);
      return true;
    });
  return [...deduped].reverse();
}

/***
 * MARK: isArrivalTimelineStatus
 * @description True for stored timeline statuses that record an arrival into
 *   the row's stage (destination), as opposed to outcome rows (Failed,
 *   Completed) that record what happened in the row's stage (source). The
 *   backend only writes Moved/Advanced arrivals today, but the match is
 *   case-insensitive and prefix-tolerant ('Advanced (First Stage)',
 *   'Failed back') so a status-string drift reintroduces no duplicate; any
 *   other status fails open (treated as an outcome, never suppressed).
 * @example isArrivalTimelineStatus('Advanced (First Stage)') => true
 * @example isArrivalTimelineStatus('Failed') => false
 * @param {string} [status] - Stored timeline row status.
 * @returns {boolean} True when the row is an arrival into its stage.
 ***/
function isArrivalTimelineStatus(status) {
  const normalized = typeof status === 'string' ? status.trim().toLowerCase() : '';
  return (
    normalized === 'moved' ||
    normalized.startsWith('moved ') ||
    normalized === 'advanced' ||
    normalized.startsWith('advanced ') ||
    normalized === 'failed back' ||
    normalized.startsWith('failed back ')
  );
}

/***
 * MARK: isFailedTimelineOutcome
 * @description True for stored Failed rows: the outcome of a visit to the
 *   row's stage, carrying the failure reason. Never suppressed.
 * @example isFailedTimelineOutcome('Failed') => true
 * @example isFailedTimelineOutcome('Failed back') => false
 * @param {string} [status] - Stored timeline row status.
 * @returns {boolean} True for Failed outcome rows.
 ***/
function isFailedTimelineOutcome(status) {
  return typeof status === 'string' && status.trim().toLowerCase() === 'failed';
}

/***
 * MARK: pickRunAttribution
 * @description Picks a timeline entry's run-attribution fields
 *   (`harnessId`, `modelRef`, `aliasName`, `targetIndex`) for display,
 *   passing only fields that exist — a row without attribution yields an
 *   empty object, so nothing (never a placeholder) renders for it.
 * @example pickRunAttribution({ harnessId: 'pi' }) => { harnessId: 'pi' }
 * @example pickRunAttribution({ stage: 'CI' }) => {}
 * @param {Object} [entry] - Timeline entry.
 * @returns {Object} Only the attribution fields present on the entry.
 ***/
function pickRunAttribution(entry) {
  if (!entry || typeof entry !== 'object') return {};
  const picked = {};
  for (const key of ['harnessId', 'modelRef', 'aliasName', 'targetIndex']) {
    if (entry[key] !== undefined) picked[key] = entry[key];
  }
  return picked;
}

/***
 * MARK: buildDisplayTimeline
 * @description Builds the history rows the inspector shows, newest first, from
 *   stored arrivals plus one live current-stage row. Stored arrivals record
 *   stage = destination, so the newest arrival into the live stage would render
 *   the same stage twice (live Active row plus stored Moved/Advanced row with
 *   the previous stage's duration) — that row is suppressed, but only when
 *   every stored row newer than it is a same-stage Failed outcome (the live
 *   row supersedes exactly the current visit's arrival, never a past visit's).
 *   Failed, Completed, other-stage, and unknown-status rows are never
 *   suppressed, so failure reasons and past visits stay visible. When the
 *   live row supersedes the current visit's arrival row it inherits that
 *   row's run attribution (the stage's dispatch-stamped model choice).
 *   Completed tasks and the full-page view pass includeLiveRow false and see
 *   the full stored history.
 * @example buildDisplayTimeline({ storedTimeline: [{ stage: 'Plan', status: 'Moved', duration: '9s', timestamp: 't2' }], stages: [{ id: '2', name: 'Plan' }], currentStageName: 'Plan', liveDurationLabel: '3s in stage', includeLiveRow: true }) => [{ stage: 'Plan', status: 'Active' }]
 * @example buildDisplayTimeline({ storedTimeline: [], currentStageName: 'In Progress', includeLiveRow: false }) => [{ stage: 'In Progress', status: 'Active' }]
 * @param {Object} [args] - Timeline display inputs.
 * @param {Array<Object>} [args.storedTimeline=[]] - Stored entries, oldest first.
 * @param {Array<Object>} [args.stages=[]] - Current workflow stages for label mapping.
 * @param {string} [args.currentStageName] - Live stage name for the Active row.
 * @param {string} [args.liveDurationLabel] - Live row duration text.
 * @param {boolean} [args.includeLiveRow=false] - True for open tasks in the inspector.
 * @param {{ label?: string, tone?: string, ticking?: boolean }} [args.presentation] - Stage presentation verdict
 *   (see selectStagePresentation). A non-ticking verdict (PARKED/WAITING/DONE) renders a static settled
 *   row — never a live ACTIVE row with a growing timer.
 * @returns {Array<Object>} Display entries, most recent first. Never mutates its input.
 ***/
export function buildDisplayTimeline({
  storedTimeline = [],
  stages = [],
  currentStageName,
  liveDurationLabel,
  includeLiveRow = false,
  presentation = null,
} = {}) {
  const displayStored = selectDisplayTimeline(storedTimeline, stages);
  const fallbackStageName =
    typeof currentStageName === 'string' && currentStageName.trim()
      ? currentStageName.trim()
      : 'Current Stage';
  if (includeLiveRow) {
    // Settled tasks never tick: a parked failure renders a static PARKED row
    // (frozen text, no growing "Nm in stage" timer) so it cannot read as live.
    const settledLabel =
      presentation && presentation.ticking === false && typeof presentation.label === 'string'
        ? presentation.label.trim().toUpperCase()
        : '';
    const isSettledRow = settledLabel === 'PARKED' || settledLabel === 'WAITING' || settledLabel === 'DONE';
    if (isSettledRow) {
      const settledRow = {
        stage: fallbackStageName,
        duration: settledLabel === 'PARKED' ? 'Parked — awaiting retry' : liveDurationLabel || 'Settled',
        timestamp: settledLabel.charAt(0) + settledLabel.slice(1).toLowerCase(),
        status: settledLabel.charAt(0) + settledLabel.slice(1).toLowerCase(),
      };
      return [settledRow, ...displayStored];
    }
    const liveRow = {
      stage: fallbackStageName,
      duration: liveDurationLabel || 'In progress',
      timestamp: 'Active',
      status: 'Active',
    };
    const arrivalIndex = displayStored.findIndex(
      (entry) => entry?.stage === liveRow.stage && isArrivalTimelineStatus(entry?.status),
    );
    const superseded =
      arrivalIndex !== -1 &&
      displayStored
        .slice(0, arrivalIndex)
        .every(
          (entry) =>
            entry?.stage === liveRow.stage && isFailedTimelineOutcome(entry?.status),
        );
    if (!superseded) return [liveRow, ...displayStored];
    // The live row replaces the current visit's arrival row, so it inherits
    // that row's run attribution (stamped at the stage's dispatch): the
    // current agent run's badge stays visible while the stage is live, and a
    // human / CI stage's live row stays completely blank.
    return [
      { ...liveRow, ...pickRunAttribution(displayStored[arrivalIndex]) },
      ...displayStored.slice(0, arrivalIndex),
      ...displayStored.slice(arrivalIndex + 1),
    ];
  }
  if (displayStored.length > 0) return displayStored;
  return [
    {
      stage: fallbackStageName,
      duration: 'In progress',
      timestamp: 'Active',
      status: 'Active',
    },
  ];
}

/***
 * MARK: formatDiffStat
 * @description Renders a timeline entry's per-stage lines-changed delta as
 *   a small "+N -M" badge (added / removed lines). Returns null when the entry
 *   carries no diff data, so legacy entries render exactly as before.
 * @example formatDiffStat({ additions: 12, deletions: 3 }) => '+12 -3'
 * @example formatDiffStat({ stage: 'Idea' }) => null
 * @param {Object} [entry] - Timeline entry.
 * @returns {string|null} Badge text, or null when there is no diff data.
 ***/
export function formatDiffStat(entry) {
  const additions = entry?.additions;
  const deletions = entry?.deletions;
  if (!Number.isInteger(additions) || !Number.isInteger(deletions)) return null;
  if (additions < 0 || deletions < 0) return null;
  return `+${additions} -${deletions}`;
}

